{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/parts/rating.json
    One to five stars (a review's grade, the average of a product). The value is read as the label; the stars themselves are decoration.
    Props (p): value, label, max, size, className. -#}
{%- set v_value = (p.value ?? null) -%}
{%- set v_label = (p.label ?? null) -%}
{%- set v_max = (p.max ?? 5) -%}
{%- set v_size = (p.size ?? 16) -%}
{%- set v_full = og_round(og_min([v_max, og_max([0, v_value])])) -%}
{%- set c_1 -%}
  {%- for v_i in og_l(og_range(v_max)) %}
    {{ include('icons/LucideIcon.html.twig', {'name': 'star', 'size': og_i(v_size), 'class': og_s((og_t(og_lt(v_i, v_full)) ? 'fill-foreground text-foreground' : 'text-border'))}, with_context = false) }}
  {%- endfor %}
{%- endset -%}
{{ include('compose/Box.html.twig', {'class': og_s(og_cnv(['inline-flex items-center gap-0', (p.className ?? '')])), 'attrs': og_attrs(['role', 'img', 'aria-label', v_label, 'data-slot', 'rating', 'data-value', v_full]), 'children': c_1}, with_context = false) }}
